/**
 * Если начальный размер массива опрашиваемых событий не установлен
 */
#ifndef AWH_MAX_POLL_EVENTS_COUNT
	/**
	 * @brief Устанавливаем начальный размер массива опрашиваемых событий (64)
	 *
	 */
	#define AWH_MAX_POLL_EVENTS_COUNT 0x40
#endif

/**
 * Если верхний предел роста массива опрашиваемых событий не установлен
 */
#ifndef AWH_MAX_POLL_EVENTS_LIMIT
	/**
	 * @brief Устанавливаем верхний предел роста массива опрашиваемых событий (4096)
	 *
	 * @note Массив растёт по нагрузке, но не безгранично: за один опрос имеет смысл
	 *       забирать столько событий, сколько цикл успеет разобрать, не откладывая
	 *       надолго ни взвод дедлайнов, ни отправку накопленных изменений. Остаток
	 *       никуда не денется - дескрипторы остались готовыми, и ближайший опрос
	 *       заберёт их не ожидая
	 *
	 * @note У libevent и libev потолка нет вовсе, массив удваивается до упора и
	 *       ограничен только переполнением целого. libuv поступает наоборот: держит
	 *       массив в 1024 записи и, получив его заполненным, тут же опрашивает ядро
	 *       повторно с нулевым ожиданием. Выбран средний путь: рост до предела, за
	 *       которым разбор одной пачки начинает задерживать всё остальное
	 *
	 */
	#define AWH_MAX_POLL_EVENTS_LIMIT 0x1000
#endif

/**
 * Если длительность затишья, по которой массив событий ужимается, не установлена
 */
#ifndef AWH_POLL_EVENTS_IDLE_ROUNDS
	/**
	 * @brief Устанавливаем длительность затишья для сжатия массива событий (1024 опроса)
	 *
	 */
	#define AWH_POLL_EVENTS_IDLE_ROUNDS 0x400
#endif

